using System;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEngine;using RoadGunner;using RoadGunner.Editor;
public static class GreenwoodPocketCheck{
 static Vector2 Local(Vector3 p){var v=Quaternion.Inverse(Quaternion.Euler(0,45,0))*p;return new Vector2(v.x,v.z);}
 public static async Task<string> Main(){if(!UnityEditor.EditorApplication.isPlaying)throw new InvalidOperationException("Enter Play Mode");var s=UnityEngine.Object.FindAnyObjectByType<GameSession>();s.Restart();s.health.DamageEnabled=false;s.spawns.enabled=false;s.turret.enabled=false;foreach(var r in s.spawns.pool)r.Despawn();foreach(var b in s.spawns.buggyPool)b.Despawn();s.vehicle.ResetPose(AstraZone01Builder.World(26,43,.7f),Quaternion.Euler(0,70,0));s.input.testInput=true;s.input.testBrake=true;Application.runInBackground=true;
 try{await Task.Delay(600);s.input.testBrake=false;var route=new[]{new Vector2(32,47),new Vector2(33,53),new Vector2(38,57),new Vector2(41,58)};int index=0,minWheels=4;float deadline=Time.realtimeSinceStartup+35;while(index<route.Length&&Time.realtimeSinceStartup<deadline){var d=route[index]-Local(s.vehicle.transform.position);if(d.magnitude<2.3f){index++;continue;}s.input.testDirection=d.normalized*Mathf.Lerp(.36f,.58f,Mathf.InverseLerp(3,10,d.magnitude));minWheels=Math.Min(minWheels,s.vehicle.GroundedWheels);await Task.Delay(40);}s.input.testDirection=Vector2.zero;s.input.testBrake=true;await Task.Delay(350);bool pass=index==route.Length&&minWheels>=3;var line=(pass?"PASS ":"FAIL ")+"drive tree pocket bypass: waypoints="+index+"/4, end="+Local(s.vehicle.transform.position)+", grounded minimum="+minWheels;File.WriteAllText(AstraZone01Builder.Report+"/PocketCheck.txt",line+"\n");return line;
 }finally{s.vehicle.Body.constraints=RigidbodyConstraints.None;s.spawns.enabled=true;s.turret.enabled=true;s.Restart();}
 }}